pe\": \"input\", \"label\": \"social-insurance-number\"}]}, {\"stepId\": 98, \"stepName\": \"Summary Page\", \"components\": [{\"ref\": \"text-block\", \"type\": \"text-block\", \"label\": \"text-block\"}, {\"ref\": \"text-block-2\", \"type\": \"text-block\", \"label\": \"text-block-2\"}, {\"ref\": \"inset-text\", \"type\": \"inset-text\", \"label\": \"inset-text\"}, {\"ref\": \"summary-list\", \"type\": \"summary-list\", \"label\": \"summary-list\"}, {\"ref\": \"inset-text-2\", \"type\": \"inset-text\", \"label\": \"inset-text-2\"}, {\"ref\": \"summary-list-2\", \"type\": \"summary-list\", \"label\": \"summary-list-2\"}, {\"ref\": \"inset-text-3\", \"type\": \"inset-text\", \"label\": \"inset-text-3\"}, {\"ref\": \"summary-list-3\", \"type\": \"summary-list\", \"label\": \"summary-list-3\"}, {\"ref\": \"inset-text-4\", \"type\": \"inset-text\", \"label\": \"inset-text-4\"}, {\"ref\": \"summary-list-4\", \"type\": \"summary-list\", \"label\": \"summary-list-4\"}, {\"ref\": \"inset-text-5\", \"type\": \"inset-text\", \"label\": \"inset-text-5\"}, {\"ref\": \"summary-list-5\", \"type\": \"summary-list\", \"label\": \"summary-list-5\"}, {\"ref\": \"inset-text-6\", \"type\": \"inset-text\", \"label\": \"inset-text-6\"}, {\"ref\": \"summary-list-6\", \"type\": \"summary-list\", \"label\": \"summary-list-6\"}]}], \"conditionsWorkflowId\": 21}','2025-09-16 13:25:11','2025-09-16 13:25:11'),(1378,77,1,29,'{\"id\": \"text-block\", \"html\": \"\", \"name\": \"text-block\", \"text\": {\"en\": \"Indigenous Declaration\", \"fr\": \"La déclaration des Autochtones\"}, \"classes\": \"govuk-heading-l\"}','2025-09-17 11:44:50','2025-09-17 11:44:50'),(1379,77,2,29,'{\"id\": \"text-block-2\", \"html\": \"\", \"name\": \"text-block-2\", \"text\": {\"en\": \"By proceeding, I understand that the funding opportunity for which I am being considered is intended to increase Indigenous participation in the Canadian labour market and support First Nations, Metis and Inuit peoples’ access to sustainable and meaningful employment; and, provides access to training and employment supports to all Indigenous women in all their gender diversity, in Canada including status and non-status First Nations, Metis and Inuit peoples whether residing on or off-reserve, in urban centres and in rural, remote communities.\", \"fr\": \"En poursuivant, je comprends que l\'opportunité de financement pour laquelle je suis en considération vise à augmenter la participation des Autochtones au marché du travail canadien et à apporter des accès aux emplois et à des appuis d\'emploi durables et significatifs aux peuples Autochtones en Amérique du Nord, soit les Premières Nations, les Métis et les Inuit ; et, offre des accès à la formation et aux appuis d\'emploi à toutes les femmes autochtones de toutes leurs diversités de genre, dans toute l\'Amérique du Nord, y compris les Premières Nations, les Métis et les Inuit de statut et non-statut, qu\'elles résident sur ou hors réserve, dans des centres urbains et rurales, éloignées.\"}, \"classes\": \"govuk-body\"}','2025-09-17 11:44:50','2025-09-17 11:44:50'),(1380,77,3,29,'{\"id\": \"text-block-3\", \"html\": \"\", \"name\": \"text-block-3\", \"text\": {\"en\": \"Further, I understand that providing false or misleading information and/or omission of information by me about my Indigenous identity may result in an investigation and if the investigation is founded, will be grounds for immediate suspension of any funding and further, revocation of any Funding Agreement between me and the Native Women’s Association of Canada and/or its sub-agreement holders, and will result in a repayment of funds to Employment and Social Development Canada (ESDC), for monies I received to which I was not entitled.\", \"fr\": \"De plus, je comprends que la fourniture d\'informations fausses ou trompeuses et/ou l\'omission d\'informations par moi concernant ma identité autochtone peut entraîner une enquête et si l\'enquête est confirmée, sera les raisons d\'une suspension immédiate de toute subvention et de plus, de l\'annulation d\'un Accord de financement entre moi et l\'Association des Femmes Autochtones du Canada et/ou ses titulaires de sous-accords, et causera un remboursement de fonds à l\'Emploi et au Développement Social du Canada (ESDC), pour des monnaies dont je n\'étais pas éligible.\"}, \"classes\": \"govuk-body\"}','2025-09-17 11:44:50','2025-09-17 11:44:50'),(1381,77,4,35,'{\"id\": \"applicant_signature\", \"hint\": {\"text\": {\"en\": \"I declare that I am an Indigenous person according to the following definition: Indigenous Peoples are people who are First Nations, Inuit or Métis.\"}}, \"name\": \"indigenous_declaration\", \"label\": {\"text\": {\"en\": \"Declaration\"}, \"classes\": \"govuk-label--m\"}, \"required\": true, \"formGroup\": {\"classes\": \"\"}, \"boxPadding\": \"m\", \"clearLabel\": {\"text\": {\"en\": \"Clear\"}}, \"actionLabel\": {\"text\": {\"en\": \"Sign Now\"}}, \"placeholder\": {\"text\": {\"en\": \"First Last\"}}, \"handwritingFont\": \"cursive\", \"statusSignedText\": {\"text\": {\"en\": \"Signed\"}}, \"statusUnsignedText\": {\"text\": {\"en\": \"Not signed\"}}}','2025-09-17 11:44:50','2025-09-17 11:44:50'),(1400,79,1,26,'{\"id\": \"example-input\", \"hint\": {\"text\": {\"en\": \"We need your Social Insurance Number to process your request. It will only be used to confirm your eligibility and won’t be shared without your permission.  Your 9-digit Social Insurance Number (e.g., 123 456 789)\", \"fr\": \"Nous avons besoin de votre numéro d\'assurance sociale pour traiter votre demande. Il ne sera utilisé qu\'à des fins de confirmation de votre éligibilité et ne sera pas partagé sans votre autorisation. Votre numéro d\'assurance sociale de 9 chiffres (par exemple, 123 456 789)\"}}, \"mask\": \"sin-ca\", \"name\": \"social-insurance-number\", \"type\": \"text\", \"label\": {\"text\": {\"en\": \"What is your Social Insurance Number (SIN)?\", \"fr\": \"Quel est votre numéro d\'assurance sociale (SIN) ?\"}, \"classes\": \"govuk-label--m\"}, \"value\": {\"en\": \"\"}, \"prefix\": {\"text\": \"\"}, \"suffix\": {\"text\": \"\"}, \"classes\": \"govuk-input\", \"pattern\": \"\", \"formGroup\": {\"classes\": \"\"}, \"inputmode\": \"numeric\", \"spellcheck\": false, \"validation\": {\"rules\": [], \"required\": true, \"requiredMessage\": {\"en\": \"Please enter you SIN number\", \"fr\": \"French version\"}}, \"autocomplete\": \"\", \"errorMessage\": {\"text\": {\"en\": \"\"}}}','2025-09-18 10:14:34','2025-09-18 10:14:34'),(1411,97,1,29,'{\"id\": \"text-block\", \"html\": \"\", \"name\": \"text-block\", \"text\": {\"en\": \"Household Expenses\", \"fr\": \"Exemple de texte\"}, \"classes\": \"govuk-heading-l\"}','2025-09-18 12:07:28','2025-09-18 12:07:28'),(1412,97,2,29,'{\"id\": \"text-block-2\", \"html\": \"\", \"name\": \"text-block-2\", \"text\": {\"en\": \"Please disclose all sources of monthly household income. Documentation and proof of financial situation is required prior to any approval of funding.\", \"fr\": \"Exemple de texte\"}, \"classes\": \"govuk-body-l\"}','2025-09-18 12:07:28','2025-09-18 12:07:28'),(1413,97,3,26,'{\"id\": \"example-input\", \"hint\": {\"text\": {\"en\": \"\"}}, \"name\": \"expenses-rent\", \"type\": \"text\", \"label\": {\"text\": {\"en\": \"Rent/Mortgage\"}, \"classes\": \"govuk-label--s\"}, \"value\": {\"en\": \"\"}, \"prefix\": {\"text\": \"$\"}, \"suffix\": {\"text\": \"per month\"}, \"classes\": \"govuk-input\", \"pattern\": \"\", \"formGroup\": {\"classes\": \"\"}, \"inputmode\": \"numeric\", \"spellcheck\": false, \"autocomplete\": \"\", \"errorMessage\": {\"text\": {\"en\": \"\"}}}','2025-09-18 12:07:28','2025-09-18 12:07:28'),(1414,97,4,26,'{\"id\": \"example-input-2\", \"hint\": {\"text\": {\"en\": \"\"}}, \"name\": \"expenses-utilities\", \"type\": \"text\", \"label\": {\"text\": {\"en\": \"Utilities (Hydro, water, natural gas, sewer, garbage, internet)\"}, \"classes\": \"govuk-label--s\"}, \"value\": {\"en\": \